// #01649c9c8c436e2d1a46f007 — после входа возврат на запрошенную страницу (если роли разрешено), без открытого редиректа;
// /login под вошедшим → дашборд роли. Кейсы AUTH-RT-002…005.
// Вход формой — в СОБСТВЕННОМ окне теста (asUser('guest')), данные входа — из .qa/accounts.env (как у qa-login),
// паролей в коде нет. Общие сессии .qa/auth/*.json не трогаются, «התנתקות» не нажимается.
import * as dotenv from 'dotenv';
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

dotenv.config({ path: path.resolve(__dirname, '../../../accounts.env') });

type Role = 'business' | 'user' | 'admin';
const ENV: Record<Role, [string, string]> = {
  admin: ['QA_USER_ADMIN_EMAIL', 'QA_USER_ADMIN_PASSWORD'],
  business: ['QA_USER_BUSINESS_EMAIL', 'QA_USER_BUSINESS_PASSWORD'],
  user: ['QA_USER_MEMBER_EMAIL', 'QA_USER_MEMBER_PASSWORD'],
};
const creds = (role: Role) => ENV[role].map((k) => process.env[k]) as [string | undefined, string | undefined];
const hasCreds = (...roles: Role[]) => roles.every((r) => creds(r).every(Boolean));

/** Гость открывает защищённый путь → /login (from запомнен) → вход формой. */
async function loginFrom(page: Page, role: Role, requestedPath: string) {
  await page.goto(requestedPath);
  await page.waitForURL((u) => u.pathname === '/login');
  expect(await page.evaluate(() => history.state?.usr?.from)).toBe(requestedPath);
  await submitLogin(page, role);
}

async function submitLogin(page: Page, role: Role) {
  const [email, password] = creds(role);
  await page.getByLabel('כתובת מייל').fill(email!);
  await page.getByLabel('סיסמה', { exact: true }).fill(password!);
  await page.getByRole('button', { name: 'התחברות', exact: true }).click();
  await page.waitForURL((u) => u.pathname !== '/login');
}

/** Главная business/user: «/» + h1 «שלום, …». */
async function expectHome(page: Page) {
  await expect(page.getByRole('heading', { level: 1, name: /^שלום, / })).toBeVisible();
  const url = new URL(page.url());
  expect(url.origin).toBe(new URL(test.info().project.use.baseURL!).origin);
  expect(url.pathname).toBe('/');
}

test.describe('Вход — возврат на запрошенную страницу (#01649c9c8c436e2d1a46f007)', () => {
  // Источник всех ожиданий: «מה רצוי» — «אחרי התחברות המשתמש מוחזר לדף שביקש אם מותר לו»; AC F-05 — дашборд роли.

  test('business: запросил /settings/users → после входа /settings/users @desktop @prod-safe #01649c9c8c436e2d1a46f007', async ({ asUser }) => {
    test.skip(!hasCreds('business'), 'нет QA_USER_BUSINESS_EMAIL / _PASSWORD в .qa/accounts.env');
    const page = await asUser('guest');
    await loginFrom(page, 'business', '/settings/users');
    await expect(page.getByRole('heading', { level: 1, name: 'משתמשים והזמנות' })).toBeVisible();
    expect(new URL(page.url()).pathname).toBe('/settings/users');
  });

  test('admin: запросил /admin/providers → после входа /admin/providers @desktop @prod-safe #01649c9c8c436e2d1a46f007', async ({ asUser }) => {
    test.skip(!hasCreds('admin'), 'нет QA_USER_ADMIN_EMAIL / _PASSWORD в .qa/accounts.env');
    const page = await asUser('guest');
    await loginFrom(page, 'admin', '/admin/providers');
    await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();
    expect(new URL(page.url()).pathname).toBe('/admin/providers');
    await expect(page.getByRole('heading', { name: 'המסך לא נמצא' })).toHaveCount(0);
  });

  test('business: запросил /admin/businesses (не разрешено) → после входа главная «שלום, …» @desktop @prod-safe #01649c9c8c436e2d1a46f007', async ({ asUser }) => {
    test.skip(!hasCreds('business'), 'нет QA_USER_BUSINESS_EMAIL / _PASSWORD в .qa/accounts.env');
    const page = await asUser('guest');
    await loginFrom(page, 'business', '/admin/businesses');
    await expectHome(page);
    await expect(page.getByRole('heading', { name: 'אין לך הרשאה למסך הזה' })).toHaveCount(0);
  });

  test('user (מנהל/ת מגייס/ת): запросил /settings/users (не разрешено) → после входа главная «שלום, …» @desktop @prod-safe #01649c9c8c436e2d1a46f007', async ({ asUser }) => {
    test.skip(!hasCreds('user'), 'нет QA_USER_MEMBER_EMAIL / _PASSWORD в .qa/accounts.env');
    const page = await asUser('guest');
    await loginFrom(page, 'user', '/settings/users');
    await expectHome(page);
    await expect(page.getByRole('heading', { name: 'אין לך הרשאה למסך הזה' })).toHaveCount(0);
  });

  for (const evil of ['https://evil.example', '//evil.example']) {
    test(`business: from='${evil}' → после входа главная своего домена (нет открытого редиректа) @desktop @prod-safe #01649c9c8c436e2d1a46f007`, async ({ asUser }) => {
      test.skip(!hasCreds('business'), 'нет QA_USER_BUSINESS_EMAIL / _PASSWORD в .qa/accounts.env');
      const page = await asUser('guest');
      await page.goto('/login');
      await expect(page.getByRole('heading', { level: 1, name: 'התחברות' })).toBeVisible();
      // Тот же путь, что после редиректа гостя: router читает from из history.state.usr.
      await page.evaluate((from) => history.replaceState({ usr: { from }, key: 'qaevil', idx: 0 }, '', '/login'), evil);
      await page.reload();
      expect(await page.evaluate(() => history.state?.usr?.from)).toBe(evil);
      await submitLogin(page, 'business');
      await expectHome(page);
    });
  }
});

test.describe('/login под вошедшим — дашборд роли (#01649c9c8c436e2d1a46f007)', () => {
  // Сохранённые сессии, без пароля. Источник: AC F-05 — «מועבר לדשבורד המתאים להרשאתו».
  for (const role of ['business', 'user'] as const) {
    test(`${role}: /login → «/» «שלום, …» @desktop @prod-safe #01649c9c8c436e2d1a46f007`, async ({ asUser }) => {
      const page = await asUser(role);
      await page.goto('/login');
      await page.waitForURL((u) => u.pathname !== '/login');
      await expectHome(page);
    });
  }

  test('admin: /login → /admin/businesses «בתי העסק» @desktop @prod-safe #01649c9c8c436e2d1a46f007', async ({ asUser }) => {
    const page = await asUser('admin');
    await page.goto('/login');
    await page.waitForURL((u) => u.pathname === '/admin/businesses');
    await expect(page.getByRole('heading', { level: 1, name: 'בתי העסק' })).toBeVisible();
  });
});
